// 旧manifest反读原人口revision：从同一原cohort逆演有明确映射的转移/损失，不以当前人数冒旧时点。
#include "population_transport.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class T>Outcome<T> fail(const char* code,const StableId& id){return {false,{},common_failure(code,id).error};}
const PopulationTransfer* transfer_for_source(const LocalEconomyState& economy,const PopulationTransportState& state,const StableId& cohort,const SourceRef& source){if(source.domain=="local_economy"&&source.kind=="population_transfer")return economy.population_transfers.find(source.id);for(const auto& row:state.transport_bindings.rows())if(row.second.transport_cohort_id==cohort&&same_source_ref(row.second.registration_source_ref,source)&&row.second.source_population_transfer_ref)return economy.population_transfers.find(*row.second.source_population_transfer_ref);return nullptr;}
}
Outcome<PopulationRevisionView> read_population_revision_source(const LocalEconomyState& economy,const PopulationTransportState& state,const CivilianPopulationRef& ref){const auto* cohort=economy.cohorts.find(ref.cohort_id);const auto* current=state.source_revisions.find(ref.cohort_id);if(!cohort||!current||ref.population_revision<1||ref.population_revision>current->revision||!current->location_binding_ref)return fail<PopulationRevisionView>("PopulationRevisionUnavailable",ref.cohort_id);PopulationRevisionView out{ref,cohort->headcount,cohort->labor_capacity,current->condition_source_ref,*current->location_binding_ref,{}};std::set<StableId> count_sources;Integer expected=current->revision;for(auto it=state.revision_sources.rbegin();it!=state.revision_sources.rend();++it){const auto& event=*it;if(event.cohort_id!=ref.cohort_id)continue;if(event.revision_after!=expected||event.revision_after!=event.revision_before+1)return fail<PopulationRevisionView>("PopulationRevisionHistoryMismatch",ref.cohort_id);const auto* transfer=transfer_for_source(economy,state,ref.cohort_id,event.actual_source);const PopulationLoss* loss=nullptr;if(event.actual_source.domain=="local_economy"&&event.actual_source.kind=="population_loss")loss=economy.population_losses.find(event.actual_source.id);if(transfer){if(transfer->from_cohort_id!=ref.cohort_id&&transfer->to_cohort_id!=ref.cohort_id)return fail<PopulationRevisionView>("PopulationRevisionTransferMismatch",event.actual_source.id);if(!count_sources.insert(transfer->id).second)return fail<PopulationRevisionView>("DuplicatePopulationCountSource",transfer->id);out.original_count_sources.push_back({"local_economy","population_transfer",transfer->id});if(event.revision_after>ref.population_revision){const Integer sign=transfer->from_cohort_id==ref.cohort_id?1:-1;Integer head=0,labor=0;if(__builtin_mul_overflow(sign,transfer->count,&head)||__builtin_mul_overflow(sign,transfer->labor_eligible_count,&labor)||__builtin_add_overflow(out.headcount,head,&out.headcount)||__builtin_add_overflow(out.labor_capacity,labor,&out.labor_capacity))return fail<PopulationRevisionView>("PopulationRevisionOverflow",ref.cohort_id);}}else if(loss){if(loss->cohort_id!=ref.cohort_id||!count_sources.insert(loss->id).second)return fail<PopulationRevisionView>("PopulationRevisionLossMismatch",loss->id);out.original_count_sources.push_back(event.actual_source);if(event.revision_after>ref.population_revision&&(__builtin_add_overflow(out.headcount,loss->count,&out.headcount)||__builtin_add_overflow(out.labor_capacity,loss->labor_eligible_count,&out.labor_capacity)))return fail<PopulationRevisionView>("PopulationRevisionOverflow",ref.cohort_id);}else{bool location_event=false;for(const auto& b:state.transport_bindings.rows())if(b.second.transport_cohort_id==ref.cohort_id&&same_source_ref(b.second.registration_source_ref,event.actual_source))location_event=true;for(const auto& r:state.releases){const auto* b=state.transport_bindings.find(r.binding_id);if(b&&b->transport_cohort_id==ref.cohort_id&&same_source_ref(r.actual_handover_source,event.actual_source))location_event=true;}if(!location_event)return fail<PopulationRevisionView>("PopulationRevisionOriginalSourceRequired",event.actual_source.id);}if(event.revision_after==ref.population_revision){out.condition_source_ref=event.condition_after;if(!event.location_after)return fail<PopulationRevisionView>("PopulationRevisionLocationMissing",ref.cohort_id);out.location_binding_ref=*event.location_after;}expected=event.revision_before;}
 // Every original count mutation is accounted, including changes written by an older domain owner.
 for(const auto& row:economy.population_transfers.rows())if((row.second.from_cohort_id==ref.cohort_id||row.second.to_cohort_id==ref.cohort_id)&&!count_sources.count(row.first))return fail<PopulationRevisionView>("UntrackedPopulationTransferRevision",row.first);for(const auto& row:economy.population_losses.rows())if(row.second.cohort_id==ref.cohort_id&&!count_sources.count(row.first))return fail<PopulationRevisionView>("UntrackedPopulationLossRevision",row.first);if(expected!=0&&expected!=1)return fail<PopulationRevisionView>("PopulationRevisionBaseMismatch",ref.cohort_id);if(ref.population_revision==1&&expected==1){out.condition_source_ref.reset();out.location_binding_ref={"local_economy","initial_cohort_site",ref.cohort_id};}if(out.headcount<0||out.labor_capacity<0||out.labor_capacity>out.headcount)return fail<PopulationRevisionView>("PopulationRevisionCountMismatch",ref.cohort_id);std::optional<StableId> active;for(const auto& row:state.transport_bindings.rows()){const auto& b=row.second;if(b.transport_cohort_id!=ref.cohort_id)continue;Integer start=0,end=INT64_MAX;for(const auto& event:state.revision_sources)if(event.cohort_id==ref.cohort_id){if(same_source_ref(event.actual_source,b.registration_source_ref))start=event.revision_after;for(const auto& release:state.releases)if(release.binding_id==b.binding_id&&same_source_ref(event.actual_source,release.actual_handover_source))end=event.revision_after;}if(!start)return fail<PopulationRevisionView>("PopulationBindingRevisionMissing",b.binding_id);if(start<=ref.population_revision&&ref.population_revision<end){if(active)return fail<PopulationRevisionView>("DuplicateHistoricalPopulationBinding",ref.cohort_id);active=b.binding_id;}}if(active!=ref.transport_binding_id)return fail<PopulationRevisionView>("HistoricalPopulationBindingMismatch",ref.cohort_id);return {true,std::move(out),{}};}
}
